from datetime import date
from decimal import Decimal, ROUND_HALF_UP

CENT = Decimal("0.01")


def _parse_month(month):
    """Parse a "YYYY-MM" string into (year, month)."""
    try:
        year_s, month_s = month.split("-")
        year, mon = int(year_s), int(month_s)
    except (AttributeError, ValueError):
        raise ValueError(f"month must look like 'YYYY-MM', got {month!r}")
    if not 1 <= mon <= 12:
        raise ValueError(f"month number out of range in {month!r}")
    return year, mon


def _in_month(t, year, mon):
    return t.day.year == year and t.day.month == mon


def _exact(amount):
    # repr() gives the shortest decimal string for a float, so 54.2 -> 54.2
    # instead of its binary approximation; sums then stay exact.
    return Decimal(repr(float(amount)))


def summarize(transactions, month):
    """Return {category: net total} for the calendar month, rounded to 2 decimals.

    Refunds (negative amounts) reduce the total. Categories whose net total
    is exactly zero are omitted.
    """
    year, mon = _parse_month(month)
    totals = {}
    for t in transactions:
        if _in_month(t, year, mon):
            totals[t.category] = totals.get(t.category, Decimal(0)) + _exact(t.amount)
    return {
        cat: float(total.quantize(CENT, rounding=ROUND_HALF_UP))
        for cat, total in totals.items()
        if total != 0
    }


def find_duplicates(transactions):
    """Return (earlier_id, later_id) pairs that look like duplicate charges.

    A pair shares payee and amount, its dates are at most 2 days apart
    (inclusive), and neither is a refund (negative amount). "Earlier" means
    the smaller (date, id). The list is sorted by the earlier transaction's
    date, then its id.
    """
    candidates = [t for t in transactions if t.amount >= 0]
    pairs = []
    for i, a in enumerate(candidates):
        for b in candidates[i + 1:]:
            if a.payee != b.payee or a.amount != b.amount:
                continue
            if abs((a.day - b.day).days) > 2:
                continue
            first, second = sorted((a, b), key=lambda t: (t.day, t.id))
            pairs.append((first, second))
    pairs.sort(key=lambda p: (p[0].day, p[0].id, p[1].day, p[1].id))
    return [(first.id, second.id) for first, second in pairs]

